/**
 * 负责分别推导狼队知识、聊天参与和刀权。输入为当前 World 角色及明确运行政策；输出保留队友、狼聊、狼刀名单和事件受众。狼阵营本身不等于拥有全部狼队权限，不据历史知识授予当前刀权。
 */
import { scholarMentorPackBlocked } from "./scholar_mentor/night_frame";
import { animalPackKnifeBlocked } from "./animal_dream/authority";
import { nightmareKnifeBlocked } from "./nightmare_shadow/night_frame";
import { weddingMember, ghostBrideReady, weddingSetup } from "./ghost_bride/authority";
import { initialIdentitySetupReady } from "./initial_identity/deal";
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import {
  Camp,
  type EntityId,
  type GameEvent,
  type WolfTeamEventType,
} from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import type { RoleCatalog } from "./catalog";
import type { WolfTeamPermissions } from "./contracts";

const NO_ACCESS: WolfTeamPermissions = Object.freeze({
  recognizedByPack: false,
  recognizes: "none",
  canChat: false,
  canVoteForKill: false,
});

/** 只查询角色当前的明确权限；不依赖全局目录，也不写入角色或库存。 */
export function wolfTeamPermissions(
  role: RoleComponent | undefined,
  catalog: RoleCatalog,
  world?: World,
): WolfTeamPermissions {
  if (world && !initialIdentitySetupReady(world)) return NO_ACCESS;
  if (!role || role.camp !== Camp.Wolf) return NO_ACCESS;
  if (world && weddingSetup(world) && (!ghostBrideReady(world) || weddingMember(world, role)))
    return NO_ACCESS;
  const permissions = catalog.runtime(role.role)?.wolfTeam;
  const result =
    typeof permissions === "function" ? permissions(role, world) : (permissions ?? NO_ACCESS);
  return world &&
    (nightmareKnifeBlocked(world) ||
      scholarMentorPackBlocked(world) ||
      animalPackKnifeBlocked(world))
    ? { ...result, canVoteForKill: false }
    : result;
}

export function knownWolfTeammates(
  world: World,
  actorId: EntityId,
  catalog: RoleCatalog,
): EntityId[] {
  const viewer = wolfTeamPermissions(world.getComponent(actorId, COMPONENT.Role), catalog, world);
  if (viewer === NO_ACCESS) return [];
  const role = world.getComponent(actorId, COMPONENT.Role);
  const snapshot = role?.camp === Camp.Wolf && catalog.runtime(role.role)?.knownTeammates;
  if (snapshot)
    return [...new Set(snapshot(role!, world))]
      .filter((id) => id !== actorId && world.getComponent(id, COMPONENT.Role)?.camp === Camp.Wolf)
      .sort((a, b) => a - b);
  if (viewer.recognizes === "none") return [];
  // 身份知识独立于尚未公告的死亡，不能按真实存活状态重写已知队友。
  return world
    .entityIds()
    .filter((id) => {
      if (id === actorId) return false;
      const target = world.getComponent(id, COMPONENT.Role);
      if (target?.camp !== Camp.Wolf) return false;
      if (viewer.recognizes === "all") return true;
      if (viewer.recognizes === "pack")
        return wolfTeamPermissions(target, catalog, world).recognizedByPack;
      return viewer.recognizes.includes(target.role);
    })
    .sort((a, b) => a - b);
}

export function wolfChatParticipants(world: World, catalog: RoleCatalog): EntityId[] {
  return world
    .getAliveEntityIds()
    .filter(
      (id) => wolfTeamPermissions(world.getComponent(id, COMPONENT.Role), catalog, world).canChat,
    )
    .sort((a, b) => a - b);
}

export function wolfKnifeHolders(world: World, catalog: RoleCatalog): EntityId[] {
  return world
    .getAliveEntityIds()
    .filter(
      (id) =>
        wolfTeamPermissions(world.getComponent(id, COMPONENT.Role), catalog, world).canVoteForKill,
    )
    .sort((a, b) => a - b);
}

/** 在事实发布时捕获一次受众；此受众包只用于引擎／Tape，不随后续阵营变化补发历史。 */
export function wolfTeamEvent<K extends WolfTeamEventType>(
  world: World,
  catalog: RoleCatalog,
  event: Omit<Extract<GameEvent, { type: K }>, "audience">,
): Extract<GameEvent, { type: K }> {
  const recipients = wolfChatParticipants(world, catalog);
  if (event.type === "wolf_kill_vote_cast") recipients.push(...wolfKnifeHolders(world, catalog));
  return {
    ...event,
    audience: Object.freeze([...new Set(recipients)].sort((a, b) => a - b)),
  } as Extract<GameEvent, { type: K }>;
}

/**
 * 负责在校验和提交时点查询原生自爆资格。输入为当前角色及 Catalog 的运行贡献；输出为原布尔资格，不写状态、开启自爆窗口或授予请求权限。
 */
import type { RoleComponent } from "../../../core/domain/components/role";
import type { RoleCatalog } from "./catalog";

export function canRoleSelfDestruct(role: RoleComponent, catalog: RoleCatalog): boolean {
  const capability = catalog.runtime(role.role)?.canSelfDestruct;
  return typeof capability === "function" ? capability(role) : capability === true;
}

/**
 * 负责通过配置的角色 hook 提交已选自爆。输入为捕获玩家、已校验选择和当前窗口；输出为原爆炸效果与死亡提案。不复用已撤销玩家，不执行最终阶段／胜负封盘。
 */
import { RED_MOON_ROLE } from "../roles/red_moon_apostle/ports";
import { commitDemonRedMoonBlast } from "../roles/demon_hunter/authority";
import { canRoleSelfDestruct } from "../roles/self_destruct_capability";
import {
  weddingMember,
  weddingSetup,
  ghostBrideReady,
  swallowWeddingBadges,
} from "../roles/ghost_bride/authority";
import {
  ActionWindow,
  Phase,
  Role,
  DeathCause,
  type SelfDestructSelection,
  type DeathSources,
  type GameEvent,
} from "../../../core/domain/model";
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import type { World } from "../../../core/domain/world";
import { getWhiteWolfKingState, consumeWhiteWolfDetonation } from "../roles/white_wolf_king/ports";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";

/** 仅提交本自爆能力的资源、事件和事实，返回死亡提案；实际死亡写入由结算器负责。 */
export function commitSelfDestructSelection(
  world: World,
  choice: SelfDestructSelection,
  window: ActionWindow,
  phase: Phase,
  events: GameEvent[],
): { deaths: number[]; sources: DeathSources } | null {
  if (
    !Object.values(ActionWindow).includes(window) ||
    phase !== (window === ActionWindow.OnPreVote ? Phase.Voting : Phase.Day)
  )
    return null;
  const role = world.getComponent(choice.actorId, COMPONENT.Role);
  if (!role || !world.getComponent(choice.actorId, COMPONENT.Alive)?.alive) return null;
  const ownsWedding = weddingSetup(world) !== null;
  if (
    ownsWedding &&
    (!ghostBrideReady(world) ||
      role.role !== Role.Wolf ||
      weddingMember(world, role) ||
      ![ActionWindow.OnPreElection, ActionWindow.OnPreVote].includes(window))
  )
    return null;
  const deaths = [choice.actorId],
    sources: DeathSources = { [choice.actorId]: [DeathCause.SelfDestruct] };
  if (choice.kind === "ordinary") {
    const redMoon = String(role.role) === RED_MOON_ROLE;
    if (
      choice.targetId !== null ||
      (redMoon
        ? ![ActionWindow.OnPreElection, ActionWindow.OnPreVote].includes(window)
        : !canRoleSelfDestruct(role, getDefaultRoleCatalog()))
    )
      return null;
    const moon = redMoon ? commitDemonRedMoonBlast(world, choice.actorId) : null;
    if (redMoon && !moon) return null;
    if (ownsWedding) swallowWeddingBadges(world, events);
    events.push({
      timestamp: Date.now(),
      type: "wolf_self_destruct",
      payload: { wolfId: choice.actorId, window },
    });
    if (moon?.sealsNight)
      events.push({
        timestamp: Date.now(),
        type: "red_moon_night_sealed",
        payload: { actorId: choice.actorId, day: moon.day, night: moon.day + 1 },
      });
  } else if (choice.kind === "white_wolf_king") {
    const state = getWhiteWolfKingState(role);
    if (role.role !== Role.WhiteWolfKing || state?.canDetonate !== true) return null;
    if (choice.targetId !== null) {
      if (
        choice.targetId === choice.actorId ||
        !world.getComponent(choice.targetId, COMPONENT.Alive)?.alive
      )
        return null;
      deaths.push(choice.targetId);
      sources[choice.targetId] = [DeathCause.WhiteWolfBlast];
    }
    consumeWhiteWolfDetonation(state);
    events.push({
      timestamp: Date.now(),
      type: "white_wolf_king_self_destruct",
      payload: { actorId: choice.actorId, targetId: choice.targetId, window },
    });
  } else return null;
  return { deaths, sources };
}

/**
 * 负责白天自爆的有限规则组合：婚礼禁用、红月资格、普通自爆与白狼王库存共同约束选择。
 * 输入为原 World、角色工具表、请求构造端口、Provider、网关及窗口回调；输出为首个未被拒绝的选择或 null。
 * 并发请求保原 Promise.all 顺序；等待后按原体／生命版本／库存与目标复验，再按玩家编号尝试提交。
 * 捕获的存活组件和资源引用仅服务本次窗口；阶段 current、库存付款、死亡与最终判胜各归原 owner。
 * commit 返回 false 只跳过该选择；读取、Provider 或提交失败沿原异常传播，不补提交或回滚已写前缀。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { RED_MOON_ROLE } from "../game/mechanisms/roles/red_moon_apostle/ports";
import { demonRedMoonCanBlast } from "../game/mechanisms/roles/demon_hunter/ports";
import { canRoleSelfDestruct } from "../game/mechanisms/roles/self_destruct_capability";
import { getDefaultRoleCatalog } from "../game/mechanisms/roles/role-catalog-assembly";
import {
  weddingMember,
  weddingSetup,
  ghostBrideReady,
} from "../game/mechanisms/roles/ghost_bride/ports";
import { AliveComponent, aliveLifeVersion } from "../core/domain/components/alive";
import { COMPONENT } from "../core/domain/components/names";
import { RoleComponent } from "../core/domain/components/role";
import {
  ActionProvider,
  ActionWindow,
  Phase,
  type SelfDestructSelection,
} from "../core/domain/model";
import { RoleRegistry } from "../core/domain/registries/role_registry";
import { World } from "../core/domain/world";
import { ToolGateway } from "../game/gateway/tool_gateway";
import type { ActionRequestConstructionPort } from "../core/domain/actions";
import { getWhiteWolfKingState } from "../game/mechanisms/roles/white_wolf_king/ports";

/** 并发收集选项，按编号升序复验并尝试提交；回调明确返回 false 时跳过该选项，返回首个未被拒绝的选择。 */
export class SelfDestructWindow {
  constructor(
    private readonly world: World,
    private readonly roleRegistry: RoleRegistry,
    private readonly toolGateway: ToolGateway,
  ) {}

  async execute(
    requests: ActionRequestConstructionPort,
    provider: ActionProvider,
    window: ActionWindow,
    phase: Phase,
    isCurrent: () => boolean = () => true,
    commit?: (choice: SelfDestructSelection) => Promise<void | boolean>,
  ): Promise<SelfDestructSelection | null> {
    if (!isCurrent()) return null;
    // 先捕获所有原存活身体和生命版本；后续目标死后复活或换组件不能复用旧选择。
    const targets = new Map(
      this.world.getAliveEntityIds().map((id) => {
        const alive = this.world.getComponent(id, COMPONENT.Alive)!;
        return [id, { alive, version: aliveLifeVersion(alive) }] as const;
      }),
    );
    // 各玩家请求并发，结果排列仍由原存活名单决定；不以最早响应决定谁自爆。
    const picks = await Promise.all(
      this.world.getAliveEntityIds().map(async (actorId) => {
        const role = this.world.getComponent(actorId, COMPONENT.Role);
        if (!role) return null;
        if (
          weddingSetup(this.world) &&
          (!ghostBrideReady(this.world) || weddingMember(this.world, role))
        )
          return null;
        const tools = this.roleRegistry.getAllowedTools(role.role);
        const tool = tools.includes("self_destruct_with_target")
          ? "self_destruct_with_target"
          : tools.includes("self_destruct")
            ? "self_destruct"
            : null;
        if (!tool) return null;
        if (
          tool === "self_destruct" &&
          (String(role.role) === RED_MOON_ROLE
            ? !demonRedMoonCanBlast(this.world, actorId)
            : !canRoleSelfDestruct(role, getDefaultRoleCatalog()))
        )
          return null;
        // 白狼王复验同一库存对象；这里不消费，实际消耗仍归提交函数。
        const resource =
          tool === "self_destruct_with_target" ? getWhiteWolfKingState(role) : undefined;
        if (tool === "self_destruct_with_target" && resource?.canDetonate !== true) return null;
        const life = targets.get(actorId)!;
        const request = requests.create({
          phase,
          actionWindow: window,
          actorId,
          allowedTools: [tool],
          stage: window,
          requiresAction: false,
          summary: {
            key:
              phase === Phase.Voting
                ? "request.summary.self_destruct_pre_vote"
                : "request.summary.self_destruct",
          },
          context: {},
        });
        const action = await provider.getAction(request);
        if (
          action?.name !== tool ||
          (action.name !== "self_destruct" && action.name !== "self_destruct_with_target")
        )
          return null;
        const choice: SelfDestructSelection =
          action.name === "self_destruct"
            ? { kind: "ordinary", actorId, targetId: null }
            : { kind: "white_wolf_king", actorId, targetId: action.args.target_id };
        return { choice, action, role, resource, life };
      }),
    );
    if (!isCurrent()) return null;
    // 提交前重复检查原玩家、目标、生命版本及特殊规则；字段恢复不抹去生命版本变化。
    const stillCurrent = (pick: NonNullable<(typeof picks)[number]>) => {
      const { actorId, targetId } = pick.choice;
      if (
        !isCurrent() ||
        (weddingSetup(this.world) &&
          (!ghostBrideReady(this.world) || weddingMember(this.world, pick.role))) ||
        this.world.getComponent(actorId, COMPONENT.Role) !== pick.role ||
        this.world.getComponent(actorId, COMPONENT.Alive) !== pick.life.alive ||
        !pick.life.alive.alive ||
        pick.life.version === undefined ||
        aliveLifeVersion(pick.life.alive) !== pick.life.version
      )
        return false;
      if (String(pick.role.role) === RED_MOON_ROLE && !demonRedMoonCanBlast(this.world, actorId))
        return false;
      if (
        pick.choice.kind === "white_wolf_king" &&
        (getWhiteWolfKingState(pick.role) !== pick.resource || pick.resource?.canDetonate !== true)
      )
        return false;
      if (targetId !== null) {
        const target = targets.get(targetId);
        if (
          !target ||
          this.world.getComponent(targetId, COMPONENT.Alive) !== target.alive ||
          !target.alive.alive ||
          target.version === undefined ||
          aliveLifeVersion(target.alive) !== target.version
        )
          return false;
      }
      return true;
    };
    // 网关预检前后均复验；预检成功只产生候选，不意味着库存付款或死亡已生效。
    const valid = picks.filter(
      (pick): pick is NonNullable<typeof pick> =>
        pick !== null &&
        stillCurrent(pick) &&
        this.toolGateway.validateAndSanitize(this.world, pick.choice.actorId, pick.action, {
          phase,
          actionWindow: window,
          allowSelfDestruct: true,
        }).ok &&
        stillCurrent(pick),
    );
    // 按玩家编号串行调用可选提交；false 跳过，异常停止并保留此前提交的前缀。
    for (const pick of valid.sort((a, b) => a.choice.actorId - b.choice.actorId)) {
      if (!isCurrent()) return null;
      if (!stillCurrent(pick)) continue;
      if ((await commit?.(pick.choice)) === false) continue;
      return pick.choice;
    }
    return null;
  }
}

/** 显式空窗口列表禁用全部机会；只有未配置列表才回退到原投票前默认窗口。 */
export function isSelfDestructWindowEnabled(
  config: ReadonlyBoardConfig,
  window: ActionWindow,
): boolean {
  return config.selfDestruct?.enabledWindows === undefined
    ? window === ActionWindow.OnPreVote
    : config.selfDestruct.enabledWindows.includes(window);
}
